<script>
$(document).ready(function(){
//map
ymaps.ready(function () {
    var myMap = new ymaps.Map(\'map\', {
            center: [ 54.185882886234786, 27.832639217376713 ],
            zoom: 13,
            behaviors: [\'zoomControl\', \'typeSelector\', \'fullscreenControl\']
        }, {
            searchControlProvider: \'yandex#search\'
        });

    myMap.behaviors.disable(\'scrollZoom\');
    myMap.behaviors.enable(\'drag\');

        MyBalloonLayout = ymaps.templateLayoutFactory.createClass(
            \'<div class="popover">\' +
                \'<a class="close" href="#">&times;</a>\' +
                \'<div class="popover-inner">\' +
                    \'<div class="w-baloon">\' +
                        \'<div class="wrapper">\' +
                            \'<div class="w-baloon-name">\' +
                                \'$[properties.balloonName]\' +
                            \'</div>\' +
                        \'</div>\' +
                    \'</div>\' +
                \'</div>\' +
                \'<div class="arrow"></div>\' +
            \'</div>\', {
                
                build: function () {
                    this.constructor.superclass.build.call(this);

                    this._$element = $(\'.popover\', this.getParentElement());

                    this.applyElementOffset();

                    this._$element.find(\'.close\')
                        .on(\'click\', $.proxy(this.onCloseClick, this));
                },

                clear: function () {
                    this._$element.find(\'.close\')
                        .off(\'click\');

                    this.constructor.superclass.clear.call(this);
                },

                applyElementOffset: function () {
                    this._$element.css({
                        left: -(this._$element[0].offsetWidth / 2),
                        top: -(this._$element[0].offsetHeight + this._$element.find(\'.arrow\')[0].offsetHeight)
                    });
                },

                onCloseClick: function (e) {
                    e.preventDefault();

                    this.events.fire(\'userclose\');
                },

                _isElement: function (element) {
                    return element && element[0] && element.find(\'.arrow\')[0];
                }
            }),

    // Создание метки с пользовательским макетом балуна.
        myPlacemark = window.myPlacemark = new ymaps.Placemark([ 54.185882886234786, 27.832639217376713 ], {
            balloonName: \'[[++option_address]]\',
            }, {
                    balloonShadow: false,
                    balloonLayout: MyBalloonLayout,
                    balloonPanelMaxMapArea: 0,
                    hideIconOnBalloonOpen: false,

                    iconLayout: \'default#image\',
                    iconImageHref: \'assets/i/map_marker.png\',
                    iconImageSize: [34, 50],
                    iconImageOffset: [-17, -50]
                });
        myMap.geoObjects.add(myPlacemark);

        

});
});
